// MONEY IS AN INTEGER COUNT OF MINOR UNITS, NEVER A FLOAT.
//
// `0.1 + 0.2 === 0.30000000000000004` is the whole reason. In a currency that is not a rounding
// curiosity: it is a balance that disagrees with itself, a payment schedule whose final instalment is
// a cent out, and a total that fails reconciliation for reasons nobody can see in the numbers.
//
// So a `Money` is `{ minor, currency }` — 1234 minor units of "USD" is $12.34 — and every operation
// here stays in integers. Rounding happens EXACTLY ONCE, where a rate is applied, and it is stated
// rather than inherited from whatever the float did.
//
// CURRENCY IS CARRIED AND CHECKED. Adding USD to EUR is not a number problem, it is a modelling
// error, and silently returning a number would let it travel.
export interface Money {
  /** Signed count of minor units — cents for USD, pence for GBP. Always an integer. */
  readonly minor: number;
  /** ISO-4217-style code. Compared exactly; this module does not convert between currencies. */
  readonly currency: string;
}

/** How many minor units make one major unit. 100 for most; some currencies use 0 or 1000. */
export type MinorUnits = 1 | 10 | 100 | 1000;

export class CurrencyMismatch extends Error {
  constructor(a: string, b: string) {
    super(`cannot combine ${a} with ${b} — convert first, explicitly`);
    this.name = "CurrencyMismatch";
  }
}

const assertInt = (n: number, what: string): void => {
  if (!Number.isFinite(n) || !Number.isInteger(n)) throw new RangeError(`${what} must be a whole number of minor units, got ${n}`);
  if (!Number.isSafeInteger(n)) throw new RangeError(`${what} exceeds the safe integer range — this is not a currency amount`);
};

/** A Money from a count of MINOR units. The primitive constructor; everything else routes here. */
export function money(minor: number, currency: string): Money {
  assertInt(minor, "money");
  if (!currency.trim()) throw new RangeError("money needs a currency");
  return { minor, currency: currency.trim().toUpperCase() };
}

/**
 * A Money from a MAJOR-unit amount — `fromMajor(12.34, "USD")` is 1234 cents.
 *
 * The float is tolerated only here, at the boundary, and it is rounded rather than truncated:
 * `12.34 * 100` is `1233.9999999999998`, and truncation would lose a cent on ordinary input.
 */
export function fromMajor(major: number, currency: string, units: MinorUnits = 100): Money {
  if (!Number.isFinite(major)) throw new RangeError(`fromMajor needs a finite amount, got ${major}`);
  return money(Math.round(major * units), currency);
}

/** The major-unit value, for DISPLAY and interchange. Never feed this back into arithmetic. */
export const toMajor = (m: Money, units: MinorUnits = 100): number => m.minor / units;

const same = (a: Money, b: Money): void => {
  if (a.currency !== b.currency) throw new CurrencyMismatch(a.currency, b.currency);
};

export function add(a: Money, b: Money): Money {
  same(a, b);
  return money(a.minor + b.minor, a.currency);
}

export function subtract(a: Money, b: Money): Money {
  same(a, b);
  return money(a.minor - b.minor, a.currency);
}

export const negate = (m: Money): Money => money(-m.minor, m.currency);
export const isZero = (m: Money): boolean => m.minor === 0;
export const isNegative = (m: Money): boolean => m.minor < 0;

/** `-1 | 0 | 1`, for sorting. Throws on a currency mismatch rather than ordering incomparable things. */
export function compare(a: Money, b: Money): -1 | 0 | 1 {
  same(a, b);
  return a.minor < b.minor ? -1 : a.minor > b.minor ? 1 : 0;
}

/** Sum, which needs the currency stated because an empty list has no amount to read it from. */
export function sum(items: readonly Money[], currency: string): Money {
  return items.reduce((acc, m) => add(acc, m), money(0, currency));
}

/**
 * Scale by a RATE — an interest rate, a tax fraction, a share.
 *
 * `rounding` is explicit because the right answer depends on what is being computed: interest CHARGED
 * conventionally rounds half-up (the lender's favour), while a refund rounds toward the customer.
 * Defaulting silently is how a schedule ends up a cent adrift with nobody able to say which step did it.
 */
export type Rounding = "half-up" | "half-even" | "down" | "up";

export function scale(m: Money, rate: number, rounding: Rounding = "half-up"): Money {
  if (!Number.isFinite(rate)) throw new RangeError(`scale needs a finite rate, got ${rate}`);
  const exact = m.minor * rate;
  return money(round(exact, rounding), m.currency);
}

function round(x: number, mode: Rounding): number {
  switch (mode) {
    case "down":
      return Math.trunc(x);
    case "up":
      return x < 0 ? Math.floor(x) : Math.ceil(x);
    case "half-even": {
      // Banker's rounding — ties go to the EVEN neighbour, so a long series of .5 cases does not
      // drift upward the way half-up does. This is what reconciliation-sensitive ledgers use.
      const f = Math.floor(x);
      const diff = x - f;
      if (diff > 0.5) return f + 1;
      if (diff < 0.5) return f;
      return f % 2 === 0 ? f : f + 1;
    }
    case "half-up":
    default:
      // AWAY FROM ZERO on a tie, symmetrically. `Math.round(-0.5)` is `-0` in JS — it rounds toward
      // +∞ — so a negative amount would round the opposite way from its positive twin.
      return x < 0 ? -Math.round(-x) : Math.round(x);
  }
}

/**
 * Split `m` into `n` parts, or by WEIGHTS, losing nothing.
 *
 * The classic case: $10 three ways is not $3.33 three times — that is $9.99, and the missing cent has
 * to go somewhere. Here the remainder is distributed one minor unit at a time to the earliest parts,
 * so the parts always sum EXACTLY to the input.
 *
 * Weighted allocation is the same rule: floor each share, then hand out the remainder in order. That
 * keeps the invariant that matters (nothing created, nothing lost) without pretending the split was
 * exact when it was not.
 */
export function allocate(m: Money, weights: readonly number[]): Money[] {
  if (!weights.length) throw new RangeError("allocate needs at least one weight");
  if (weights.some((w) => !Number.isFinite(w) || w < 0)) throw new RangeError("allocate weights must be finite and non-negative");
  const total = weights.reduce((a, b) => a + b, 0);
  if (total <= 0) throw new RangeError("allocate weights must sum to more than zero");

  // Work on the magnitude so a negative amount splits as the mirror of its positive twin, rather than
  // having the remainder pushed the other way by flooring toward -∞.
  const sign = m.minor < 0 ? -1 : 1;
  const magnitude = Math.abs(m.minor);
  const shares = weights.map((w) => Math.floor((magnitude * w) / total));
  let remainder = magnitude - shares.reduce((a, b) => a + b, 0);
  for (let i = 0; remainder > 0; i = (i + 1) % shares.length) {
    shares[i] += 1;
    remainder -= 1;
  }
  return shares.map((s) => money(sign * s, m.currency));
}

/** Split into `n` equal parts, remainder to the earliest. `allocate` with flat weights. */
export const split = (m: Money, n: number): Money[] => allocate(m, new Array(n).fill(1));

/**
 * Render for a human. Locale-aware via `Intl`, falling back to a plain fixed-point string where no
 * `Intl` exists, because a formatter that throws in a worker is worse than one that reads plainly.
 */
export function format(m: Money, locale = "en-US", units: MinorUnits = 100): string {
  const major = toMajor(m, units);
  try {
    return new Intl.NumberFormat(locale, { style: "currency", currency: m.currency }).format(major);
  } catch {
    const places = units === 1 ? 0 : String(units).length - 1;
    return `${major.toFixed(places)} ${m.currency}`;
  }
}

