import { describe, it, expect } from "vitest";
import {
  money, fromMajor, toMajor, add, subtract, negate, compare, sum, scale, allocate, split, format,
  CurrencyMismatch, type Money,
} from "@/features/finance/lib/money";

const usd = (minor: number): Money => money(minor, "USD");

describe("money — integer minor units", () => {
  it("refuses a fractional minor amount", () => {
    // The whole premise: a half-cent is not a currency amount, and accepting one would put a float
    // back into the arithmetic through the front door.
    expect(() => money(10.5, "USD")).toThrow(RangeError);
    expect(() => money(NaN, "USD")).toThrow(RangeError);
    expect(() => money(Number.MAX_SAFE_INTEGER + 2, "USD")).toThrow(RangeError);
  });

  it("normalises the currency code and requires one", () => {
    expect(money(1, " usd ").currency).toBe("USD");
    expect(() => money(1, "  ")).toThrow(RangeError);
  });

  it("rounds at the float boundary rather than truncating", () => {
    // `12.34 * 100` is 1233.9999999999998 — truncation loses a cent on ordinary input, which is the
    // single most common way float money goes wrong.
    expect(fromMajor(12.34, "USD").minor).toBe(1234);
    expect(fromMajor(0.1, "USD").minor + fromMajor(0.2, "USD").minor).toBe(fromMajor(0.3, "USD").minor);
    expect(toMajor(usd(1234))).toBe(12.34);
  });
});

describe("money — combining", () => {
  it("adds and subtracts exactly", () => {
    expect(add(usd(1234), usd(66)).minor).toBe(1300);
    expect(subtract(usd(1000), usd(1250)).minor).toBe(-250);
  });

  it("REFUSES to combine two currencies", () => {
    // Not a number problem — a modelling error. Returning a number would let it travel.
    expect(() => add(usd(1), money(1, "EUR"))).toThrow(CurrencyMismatch);
    expect(() => compare(usd(1), money(1, "EUR"))).toThrow(CurrencyMismatch);
  });

  it("sums an EMPTY list to zero of the stated currency", () => {
    // The currency is a parameter because an empty list has no amount to read it from — inferring it
    // would mean guessing, and a zero in the wrong currency combines silently later.
    expect(sum([], "GBP")).toEqual({ minor: 0, currency: "GBP" });
    expect(sum([usd(100), usd(250)], "USD").minor).toBe(350);
  });

  it("orders, and negates", () => {
    expect([usd(300), usd(100), usd(200)].sort(compare).map((m) => m.minor)).toEqual([100, 200, 300]);
    expect(negate(usd(-250)).minor).toBe(250);
  });
});

describe("money — scaling by a rate", () => {
  it("rounds half-up AWAY FROM ZERO, symmetrically", () => {
    // `Math.round(-0.5)` is -0 in JS: it rounds toward +∞, so a negative amount would round the
    // opposite way from its positive twin and a refund would not mirror its charge.
    expect(scale(usd(5), 0.5).minor).toBe(3);
    expect(scale(usd(-5), 0.5).minor).toBe(-3);
  });

  it("offers banker's rounding, which does not drift on a long series of ties", () => {
    expect(scale(usd(5), 0.5, "half-even").minor).toBe(2); // 2.5 → 2, the even neighbour
    expect(scale(usd(15), 0.5, "half-even").minor).toBe(8); // 7.5 → 8
  });

  it("truncates toward zero on `down`, and away on `up`", () => {
    expect(scale(usd(199), 0.5, "down").minor).toBe(99);
    expect(scale(usd(-199), 0.5, "down").minor).toBe(-99);
    expect(scale(usd(101), 0.5, "up").minor).toBe(51);
    expect(scale(usd(-101), 0.5, "up").minor).toBe(-51);
  });
});

describe("money — allocation loses nothing", () => {
  it("splits $10 three ways WITHOUT losing the cent", () => {
    // $3.33 three times is $9.99. The missing cent has to go somewhere, and saying so is the point.
    const parts = split(fromMajor(10, "USD"), 3);
    expect(parts.map((p) => p.minor)).toEqual([334, 333, 333]);
    expect(sum(parts, "USD").minor).toBe(1000);
  });

  it("distributes a weighted remainder in order, still losing nothing", () => {
    const parts = allocate(usd(100), [1, 1, 1, 1, 1, 1, 1]);
    expect(sum(parts, "USD").minor).toBe(100);
    expect(Math.max(...parts.map((p) => p.minor)) - Math.min(...parts.map((p) => p.minor))).toBe(1);
  });

  it("mirrors a NEGATIVE amount rather than pushing the remainder the other way", () => {
    // Flooring toward -∞ would give [-334,-333,-333] a different shape from its positive twin.
    const pos = split(usd(1000), 3).map((p) => p.minor);
    const neg = split(usd(-1000), 3).map((p) => p.minor);
    expect(neg).toEqual(pos.map((n) => -n));
    expect(sum(split(usd(-1000), 3), "USD").minor).toBe(-1000);
  });

  it("holds the invariant across many awkward splits", () => {
    // The property that matters: nothing created, nothing lost, whatever the shape.
    for (const total of [1, 7, 99, 100, 1234, 99999]) {
      for (const n of [1, 2, 3, 7, 11]) {
        expect(sum(split(usd(total), n), "USD").minor, `${total} into ${n}`).toBe(total);
      }
    }
  });

  it("refuses weights that cannot describe a split", () => {
    expect(() => allocate(usd(100), [])).toThrow(RangeError);
    expect(() => allocate(usd(100), [0, 0])).toThrow(RangeError);
    expect(() => allocate(usd(100), [1, -1])).toThrow(RangeError);
  });
});

describe("money — display", () => {
  it("formats for a human without going back through arithmetic", () => {
    expect(format(usd(123456))).toContain("1,234.56");
    // 123456 MINOR units is EUR 1,234.56 — the unit confusion this test first made is exactly the
    // one the type exists to prevent, so it stays written down.
    expect(format(money(123456, "EUR"), "de-DE")).toContain("1.234,56");
  });
});
